<span class="line">  <span class="token keyword">const</span> log <span class="token operator">=</span> <span class="token function">getLog</span><span class="token punctuation">(</span><span class="token string">&#39;Router&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
